arguments.command:
bash -lc 'set -e; ed -s src/vm.c <<'ED'
2670,2681d
2670a
    CASE(OP_ARYCAT, B) {
      mrb_value left = regs[a];
      mrb_value right = regs[a+1];
      mrb_value splat = mrb_ary_splat(mrb, right);
      if (mrb_nil_p(left)) {
        regs[a] = splat;
      }
      else {
        mrb_assert(mrb_array_p(left));
        mrb_ary_concat(mrb, left, splat);
      }
      mrb_gc_arena_restore(mrb, ai);
      NEXT;
    }
.
wq
ED'

bash -lc 'set -e; tmp_head=$(mktemp); tmp_tail=$(mktemp); tmp_block=$(mktemp); head -n 2669 src/vm.c > "$tmp_head"; tail -n +2682 src/vm.c > "$tmp_tail"; cat > "$tmp_block" << EOS
    CASE(OP_ARYCAT, B) {
      mrb_value a_reg = regs[a];
      mrb_value b_reg = regs[a+1];
      mrb_value splat = mrb_ary_splat(mrb, b_reg);
      if (mrb_nil_p(a_reg)) {
        regs[a] = splat;
      } else {
        mrb_assert(mrb_array_p(a_reg));
        mrb_ary_concat(mrb, a_reg, splat);
      }
      mrb_gc_arena_restore(mrb, ai);
      NEXT;
    }
EOS
cat "$tmp_head" "$tmp_block" "$tmp_tail" > /src/mruby/src/vm.c'
